public class NodeUtil_newQualifiedNameNodeDeclaration_TriageGen0Test {

    private CodingConvention convention;
    private JSDocInfo info;
    private Node value;

    @Before
    public void setUp() {
        convention = mock(CodingConvention.class);
        info = mock(JSDocInfo.class);
        value = mock(Node.class);
    }

    @Test
    public void testNewQualifiedNameNodeDeclaration_WithNameIsName() {
        String name = "foo.bar";
        Node nameNode = mock(Node.class);
        Node varNode = mock(Node.class);

        try (MockedStatic<NodeUtil> nodeUtilMockedStatic = Mockito.mockStatic(NodeUtil.class);
             MockedStatic<IR> irMockedStatic = Mockito.mockStatic(IR.class)) {

            // Setup: nameNode.isName() returns true
            when(nameNode.isName()).thenReturn(true);

            // Mock NodeUtil.newQualifiedNameNode to return our nameNode
            nodeUtilMockedStatic.when(() -> NodeUtil.newQualifiedNameNode(convention, name))
                .thenReturn(nameNode);

            // Mock IR.var(nameNode, value) to return varNode
            irMockedStatic.when(() -> IR.var(nameNode, value)).thenReturn(varNode);

            Node result = NodeUtil.newQualifiedNameNodeDeclaration(convention, name, value, info);

            assertNotNull(result);
            assertEquals(varNode, result);
            // Verify JSDoc was set on the result node
            Mockito.verify(varNode).setJSDocInfo(info);
        }
    }

    @Test
    public void testNewQualifiedNameNodeDeclaration_WithNameIsNotName() {
        String name = "invalid-name!";
        Node nameNode = mock(Node.class);
        Node assignNode = mock(Node.class);
        Node exprResultNode = mock(Node.class);

        try (MockedStatic<NodeUtil> nodeUtilMockedStatic = Mockito.mockStatic(NodeUtil.class);
             MockedStatic<IR> irMockedStatic = Mockito.mockStatic(IR.class)) {

            // Setup: nameNode.isName() returns false
            when(nameNode.isName()).thenReturn(false);

            // Mock NodeUtil.newQualifiedNameNode to return our nameNode
            nodeUtilMockedStatic.when(() -> NodeUtil.newQualifiedNameNode(convention, name))
                .thenReturn(nameNode);

            // Mock IR.assign(nameNode, value)
            irMockedStatic.when(() -> IR.assign(nameNode, value)).thenReturn(assignNode);
            // Mock IR.exprResult(assignNode)
            irMockedStatic.when(() -> IR.exprResult(assignNode)).thenReturn(exprResultNode);
            // Mock assignNode.getFirstChild() to return something to set JSDoc on
            when(assignNode.getFirstChild()).thenReturn(assignNode);

            Node result = NodeUtil.newQualifiedNameNodeDeclaration(convention, name, value, info);

            assertNotNull(result);
            assertEquals(exprResultNode, result);
            // Verify JSDoc was set on the first child of the result (which is the assignment)
            Mockito.verify(assignNode).setJSDocInfo(info);
        }
    }
}
